import gurobipy as gp
from gurobipy import GRB

model = gp.Model(env=env)

supply = [8, 7]
demand = [5, 10]
cost = [[10, 20], [15, 25]]
limit = [[5, 6], [4, 7]]

x = {}
for i in range(2):
    for j in range(2):
        x[(i + 1, j + 1)] = model.addVar(lb=0, name=f"x_{i+1}_{j+1}")

for i in range(2):
    model.addConstr(gp.quicksum(x[(i + 1, j + 1)] for j in range(2)) == supply[i], name=f"supply_{i+1}")

for j in range(2):
    model.addConstr(gp.quicksum(x[(i + 1, j + 1)] for i in range(2)) == demand[j], name=f"demand_{j+1}")

for i in range(2):
    for j in range(2):
        model.addConstr(x[(i + 1, j + 1)] <= limit[i][j], name=f"limit_{i+1}_{j+1}")

model.setObjective(gp.quicksum(cost[i][j] * x[(i + 1, j + 1)] for i in range(2) for j in range(2)), GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
